A-B testing de producto.ejemplo:
// Asignación determinista por hash en un SDK de experimentos
function assignVariant(userId, experimentSalt, split = 0.5) {
  const bucket = murmurHash3(`${experimentSalt}:${userId}`) / 0xffffffff;
  const variant = bucket < split ? 'control_A' : 'treatment_B';
  analytics.track('experiment_exposure', { experiment: experimentSalt, variant });
  return variant;
}

