Componentes reutilizables.ejemplo:
// Componente reutilizable parametrizado por estrategia de reintento
export async function withRetry<T>(fn: () => Promise<T>, opts = { attempts: 3, baseMs: 100 }): Promise<T> {
  for (let i = 0; i < opts.attempts; i++) {
    try { return await fn(); } catch (err) {
      if (i === opts.attempts - 1) throw err;
      await new Promise(r => setTimeout(r, opts.baseMs * 2 ** i));
    }
  }
  throw new Error('Unreachable');
}

