// Ejemplo de contrato formal verificable estáticamente en Dafny
method Retirar(saldo: int, monto: int) returns (nuevoSaldo: int)
  requires monto > 0 && saldo >= monto          // Precondición
  ensures nuevoSaldo == saldo - monto           // Postcondición
  ensures nuevoSaldo >= 0                       // Garantía de estado
{
  nuevoSaldo := saldo - monto;
}

